namespace sarif.export.trees;






using generic.stl;
using ghidra.program.model.listing;
using ghidra.util.exception;
using ghidra.util.task;
using sarif.export;
using sarif.export;
using sarif.managers;

public class SarifTreeWriter : AbstractExtWriter {

	private List<Pair<string, ProgramModule>> modules;
	private List<object> visited = new();

	public SarifTreeWriter(List<Pair<string, ProgramModule>> target, Writer baseWriter)
    : base(baseWriter)
    {
		this.modules = target;
	}

	/* @Override */
	protected void genRoot(TaskMonitor monitor)
    {
		genTree(monitor);
		root.add("trees", objects);
	}

	private void genTree(TaskMonitor monitor)
    {
		monitor.initialize(modules.size());
		foreach (Pair<string, ProgramModule> pair in modules) {
			monitor.checkCancelled();
			ExtModule isf = new ExtModule(pair.first, pair.second, visited);
			SarifObject sarif = new SarifObject(ProgramTreeSarifMgr.SUBKEY, ProgramTreeSarifMgr.KEY, getTree(isf), null);
			objects.add(getTree(sarif));
			monitor.increment();
		}
	}

}
